CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE users (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, phone varchar(16) UNIQUE NOT NULL, name varchar(150), customer_type varchar(30) NOT NULL DEFAULT 'individual', status varchar(20) NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, user_id bigint REFERENCES users, refresh_hash char(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE otp_challenges (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, phone varchar(16) NOT NULL, code_hash varchar(255) NOT NULL, attempts smallint NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE roles (id bigserial PRIMARY KEY, name varchar(50) UNIQUE NOT NULL); CREATE TABLE permissions (id bigserial PRIMARY KEY, name varchar(100) UNIQUE NOT NULL); CREATE TABLE user_roles (user_id bigint REFERENCES users, role_id bigint REFERENCES roles, PRIMARY KEY(user_id,role_id)); CREATE TABLE role_permissions (role_id bigint REFERENCES roles, permission_id bigint REFERENCES permissions, PRIMARY KEY(role_id,permission_id));
CREATE TABLE provinces (id varchar(40) PRIMARY KEY, name varchar(100) NOT NULL); CREATE TABLE cities (id varchar(40) PRIMARY KEY, province_id varchar(40) REFERENCES provinces, name varchar(100) NOT NULL);
CREATE TABLE addresses (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, user_id bigint REFERENCES users, data jsonb NOT NULL, is_default boolean DEFAULT false, version int DEFAULT 1, deleted_at timestamptz);
CREATE TABLE publishers (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, slug varchar(180) UNIQUE NOT NULL, name varchar(180) NOT NULL); CREATE TABLE series (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, slug varchar(180) UNIQUE NOT NULL, name varchar(180) NOT NULL, featured boolean DEFAULT false); CREATE TABLE categories (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, parent_id bigint REFERENCES categories, slug varchar(180) UNIQUE NOT NULL, name varchar(180) NOT NULL);
CREATE TABLE products (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, slug varchar(220) UNIQUE NOT NULL, title varchar(250) NOT NULL, subtitle varchar(250), description text, publisher_id bigint REFERENCES publishers, series_id bigint REFERENCES series, category_id bigint REFERENCES categories, status varchar(20) DEFAULT 'draft', search_text text DEFAULT '', created_at timestamptz DEFAULT now()); CREATE INDEX products_search_trgm ON products USING gin(search_text gin_trgm_ops);
CREATE TABLE skus (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, product_id bigint REFERENCES products, code varchar(80) UNIQUE NOT NULL, isbn varchar(20), attributes jsonb DEFAULT '{}', weight_grams int DEFAULT 0, minimum_order_quantity int DEFAULT 5, reference_unit_price bigint NOT NULL, fast_dispatch boolean DEFAULT false, status varchar(30) DEFAULT 'in_stock', pricing_version int DEFAULT 1);
CREATE TABLE pricing_tiers (id bigserial PRIMARY KEY, sku_id bigint REFERENCES skus ON DELETE CASCADE, min_quantity int NOT NULL, max_quantity int, unit_price bigint NOT NULL, effective_from timestamptz DEFAULT now(), effective_to timestamptz, CHECK(max_quantity IS NULL OR max_quantity>=min_quantity));
CREATE TABLE warehouses (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, name varchar(150) NOT NULL); CREATE TABLE inventory_balances (sku_id bigint REFERENCES skus, warehouse_id bigint REFERENCES warehouses, on_hand int DEFAULT 0, reserved int DEFAULT 0, safety_stock int DEFAULT 0, version int DEFAULT 1, PRIMARY KEY(sku_id,warehouse_id)); CREATE TABLE inventory_movements (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, sku_id bigint REFERENCES skus, warehouse_id bigint REFERENCES warehouses, quantity int NOT NULL, reason text NOT NULL, actor_id bigint REFERENCES users, created_at timestamptz DEFAULT now());
CREATE TABLE coupons (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, code varchar(80) UNIQUE NOT NULL, type varchar(20) NOT NULL, value bigint NOT NULL, rules jsonb DEFAULT '{}', expires_at timestamptz, active boolean DEFAULT true);
CREATE TABLE carts (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, guest_token_hash char(64) UNIQUE, user_id bigint REFERENCES users, coupon_id bigint REFERENCES coupons, version int DEFAULT 1, status varchar(20) DEFAULT 'active', created_at timestamptz DEFAULT now()); CREATE TABLE cart_items (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, cart_id bigint REFERENCES carts ON DELETE CASCADE, sku_id bigint REFERENCES skus, quantity int CHECK(quantity>0), UNIQUE(cart_id,sku_id));
CREATE TABLE checkout_quotes (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, user_id bigint REFERENCES users, cart_id bigint REFERENCES carts, cart_version int NOT NULL, snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE orders (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_number varchar(40) UNIQUE NOT NULL, user_id bigint REFERENCES users, quote_id bigint REFERENCES checkout_quotes, status varchar(30) NOT NULL, payment_status varchar(30) DEFAULT 'unpaid', snapshot jsonb NOT NULL, terms_version varchar(50) NOT NULL, reservation_expires_at timestamptz, created_at timestamptz DEFAULT now()); CREATE INDEX orders_user_created ON orders(user_id,created_at DESC);
CREATE TABLE order_lines (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_id bigint REFERENCES orders ON DELETE CASCADE, sku_id bigint REFERENCES skus, snapshot jsonb NOT NULL, quantity int NOT NULL, unit_price bigint NOT NULL, line_subtotal bigint NOT NULL, tax bigint DEFAULT 0); CREATE TABLE inventory_reservations (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_id bigint REFERENCES orders, sku_id bigint REFERENCES skus, warehouse_id bigint REFERENCES warehouses, quantity int NOT NULL, status varchar(20) DEFAULT 'active', expires_at timestamptz NOT NULL, UNIQUE(order_id,sku_id,warehouse_id)); CREATE TABLE order_status_history (id bigserial PRIMARY KEY, order_id bigint REFERENCES orders, previous_status varchar(30), new_status varchar(30) NOT NULL, reason text, actor_id bigint REFERENCES users, created_at timestamptz DEFAULT now());
CREATE TABLE payment_attempts (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_id bigint REFERENCES orders, provider varchar(50), status varchar(30), amount bigint, provider_reference varchar(150), payload_redacted jsonb, created_at timestamptz DEFAULT now()); CREATE TABLE idempotency_keys (id bigserial PRIMARY KEY, scope varchar(80), owner_key varchar(80), idem_key varchar(150), request_hash char(64), response jsonb, status_code int, UNIQUE(scope,owner_key,idem_key));
CREATE TABLE shipments (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_id bigint REFERENCES orders, data jsonb NOT NULL DEFAULT '{}', status varchar(30) DEFAULT 'created'); CREATE TABLE invoices (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, order_id bigint UNIQUE REFERENCES orders, invoice_number varchar(50) UNIQUE, snapshot jsonb NOT NULL, storage_key text);
CREATE TABLE support_categories (id varchar(50) PRIMARY KEY, title varchar(150)); CREATE TABLE support_tickets (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, user_id bigint REFERENCES users, category_id varchar(50) REFERENCES support_categories, order_id bigint REFERENCES orders, title varchar(200), status varchar(30) DEFAULT 'new', created_at timestamptz DEFAULT now()); CREATE TABLE support_messages (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, ticket_id bigint REFERENCES support_tickets ON DELETE CASCADE, sender_id bigint REFERENCES users, body text, created_at timestamptz DEFAULT now());
CREATE TABLE uploads (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, owner_id bigint REFERENCES users, storage_key text, mime varchar(100), size_bytes bigint, status varchar(20) DEFAULT 'pending'); CREATE TABLE settings (key varchar(100) PRIMARY KEY, value jsonb NOT NULL); CREATE TABLE content_pages (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, slug varchar(180) UNIQUE, title varchar(250), body text, published boolean DEFAULT false);
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, actor_id bigint REFERENCES users, action varchar(120), subject_type varchar(80), subject_id varchar(80), before_data jsonb, after_data jsonb, request_id varchar(100), created_at timestamptz DEFAULT now()); CREATE TABLE outbox_events (id bigserial PRIMARY KEY, public_id varchar(40) UNIQUE NOT NULL, event_type varchar(120), aggregate_type varchar(80), aggregate_id varchar(80), payload jsonb, attempts int DEFAULT 0, available_at timestamptz DEFAULT now(), processed_at timestamptz, last_error text);
